function renderRegions(){
 $('#regions').innerHTML=Object.keys(DATA).map(r=>`<button class="chip ${r===region?'active':''}" data-region="${r}">${r}</button>`).join('');
 $$('#regions button').forEach(b=>b.onclick=()=>{region=b.dataset.region;const label=$('#blendLabel');if(label)label.textContent=region==='오케스트라'?'오케스트라 악기 비율':region==='현대악기'?'선택 악기 비율':'전통악기 비율';renderRegions();renderInstruments();buildInstrumentCandidates(activeProfile(),false)});
}
function renderInstruments(){
 const summary=$('#selectedInstrumentSummary');if(summary)summary.textContent=`현재 실제 선택 악기 (${selected.size}개): ${[...selected].join(' · ')||'없음'}${[...selected].some(n=>!(DATA[region]||[]).some(x=>x[0]===n))?' · 다른 탭 악기도 포함됨':''}`;
 $('#instruments').innerHTML=DATA[region].map(([n,t])=>`<div class="instrument ${selected.has(n)?'active':''}"><b>${n}</b><span>${region} · ${t}<br>${sampleLabel(n)} <small class="sample-quality q-${sampleQuality(n)}">${sampleQualityText(n)}</small><br><small class="sample-source">원본 SF2: ${sampleSourceName(n)}</small><br><small class="solo-title">대표곡: ${famousSoloTitle(n)}</small></span><button data-one="${n}" class="hear-one">🔊 원음 1음</button> <button data-name="${n}" class="hear">🎼 특징 연주</button> <button data-famous="${n}" class="hear-famous">🎵 대표 독주곡</button> <button data-pick="${n}">${selected.has(n)?'✓ 선택됨':'+ 선택'}</button></div>`).join('');
 $$('.hear-one').forEach(b=>b.onclick=e=>{e.stopPropagation();previewInstrumentOne(b.dataset.one)});
 $$('.hear').forEach(b=>b.onclick=e=>{e.stopPropagation();previewInstrument(b.dataset.name)});
 $$('.hear-famous').forEach(b=>b.onclick=e=>{e.stopPropagation();previewFamousSolo(b.dataset.famous)});
 $$('[data-pick]').forEach(b=>b.onclick=()=>{const n=b.dataset.pick;manualInstrumentSelection=true;selected.has(n)?selected.delete(n):selected.add(n);renderInstruments();renderInstrumentCandidates();updateInfo()});
}
function findInstrument(name){for(const list of Object.values(DATA)){const f=list.find(x=>x[0]===name);if(f)return f}return ['피아노','건반악기','piano']}
function detectProfile(story){const s=story.toLowerCase();let best=PROFILES.generic,score=0;for(const p of Object.values(PROFILES)){const n=p.keywords.filter(k=>s.includes(k)).length;if(n>score){best=p;score=n}}return {...best}}
function genrePreset(name){if(/발라드/.test(name))return{bpm:82,meter:'4/4',arrange:'피아노와 어쿠스틱 악기로 시작해 후렴에서 현악기와 보컬 화음을 넓게 확장'};if(/EDM|하우스|테크노|트랜스|댄스|디스코|개러지|퓨처 베이스/.test(name))return{bpm:126,meter:'4/4',arrange:'짧은 전자 훅과 선명한 킥으로 시작해 후렴에서 넓은 신스와 리듬을 확장'};if(/힙합|랩|트랩|R&B|소울|펑크|가스펠/.test(name))return{bpm:94,meter:'4/4',arrange:'보컬과 그루브를 전면에 두고 벌스는 절제하며 후렴에서 코러스와 리듬을 강화'};if(/록/.test(name))return{bpm:116,meter:'4/4',arrange:'기타 리프와 라이브 드럼을 단계적으로 쌓고 마지막 후렴에서 밴드 사운드를 확장'};if(/재즈|보사노바|스윙|블루스/.test(name))return{bpm:96,meter:'4/4',arrange:'피아노와 베이스의 여백 있는 화음 위에 자연스러운 스윙과 즉흥 응답을 배치'};if(/트로트/.test(name))return{bpm:112,meter:'4/4',arrange:'또렷한 2박 리듬과 꺾임을 살리고 후렴에서 브라스와 코러스를 강조'};if(/왈츠/.test(name))return{bpm:90,meter:'3/4',arrange:'한 마디 세 박의 흐름을 살려 피아노와 현악기가 우아하게 회전'};if(/뉴에이지|앰비언트|로파이/.test(name))return{bpm:76,meter:'6/8',arrange:'피아노와 패드의 여백을 살리고 잔잔한 악기 응답으로 감정을 유지'};if(/라틴|레게|아프로|플라멩코/.test(name))return{bpm:104,meter:'4/4',arrange:'싱코페이션과 타악기 그루브를 중심으로 후렴에서 합주를 밝게 확장'};if(/영화|오케스트라|뮤지컬|합창/.test(name))return{bpm:84,meter:'4/4',arrange:'작은 피아노 모티프로 시작해 현악기·관악기·합창을 단계적으로 확장'};if(/국악|전통|월드|중국풍|일본풍|인도|중동/.test(name))return{bpm:98,meter:'4/4',arrange:'전통악기 독주와 현대 리듬이 서로 응답하며 후렴에서 세계 악기 합주로 확장'};return{bpm:100,meter:'4/4',arrange:'보컬 중심의 간결한 벌스에서 시작해 후렴에서 리듬과 화음을 선명하게 확장'}}
function storySeed(text=''){let h=2166136261;for(const ch of String(text)){h^=ch.codePointAt(0);h=Math.imul(h,16777619)}return h>>>0}
function stablePick(list,count,seed=1){const a=[...new Set(list)].filter(Boolean);if(!a.length||count<=0)return[];return a.map((name,i)=>({name,score:((storySeed(name)^seed^(i*2654435761))>>>0)})).sort((x,y)=>x.score-y.score).slice(0,count).map(x=>x.name)}
function recommendTraditionalInstruments(p,text='',salt=0){
 const entries=DATA[region]||[],seed=storySeed(`${text}|${p.genre}|${p.mood}|${p.meter}|${region}|${salt}`),slow=p.bpm<88,fast=p.bpm>112,six=p.meter==='6/8',sad=/슬픈|이별|그리|서정|아픈|잔잔|치유|편안/.test(`${p.mood} ${p.genre} ${text}`),energetic=/신나|강렬|댄스|록|축하|응원|웅장/.test(`${p.mood} ${p.genre} ${text}`);
 const scored=entries.map(([name,_,type],i)=>{let score=0;if(six&&(type==='flute'||type==='bow'||type==='pluck'))score+=3;if(sad&&(type==='bow'||type==='flute'))score+=4;if(energetic&&(type==='drum'||type==='pluck'))score+=4;if(fast&&type==='drum')score+=3;if(slow&&type==='drum')score-=2;if(/전통|국악|월드|중국풍|일본풍|인도|중동/.test(p.genre))score+=2;score+=(((seed>>>((i%4)*4))&15)/50);return{name,type,score}}).sort((a,b)=>b.score-a.score);
 const count=entries.length>=4?2:Math.min(2,entries.length),picked=[];for(const x of scored){if(!picked.length||x.type!==picked[0].type||scored.length<=2)picked.push(x.name);if(picked.length>=count)break}return picked.length?picked:stablePick(entries.map(x=>x[0]),count,seed);
}
function recommendModernInstruments(p,text='',salt=0){
 const g=String(p.genre||''),m=String(p.mood||''),seed=storySeed(`${text}|${g}|${m}|${p.bpm}|${p.meter}|${salt}`);let pools=[];
 if(/EDM|하우스|테크노|트랜스|댄스|디스코|퓨처 베이스|개러지/.test(g))pools=[['전자피아노','신시사이저','EDM 신스'],['808 베이스','베이스 기타'],['드럼 세트'],['전자 패드','합창 패드']];
 else if(/재즈|보사노바|스윙|블루스/.test(g))pools=[['전자피아노','그랜드 피아노'],['색소폰','트럼펫'],['베이스 기타','콘트라베이스'],['드럼 세트']];
 else if(/록/.test(g))pools=[['일렉 기타','어쿠스틱 기타'],['베이스 기타'],['드럼 세트'],['피아노','전자피아노','프렌치 호른']];
 else if(/영화|오케스트라|뮤지컬|합창/.test(g))pools=[['그랜드 피아노','하프'],['바이올린 섹션','첼로 섹션','비올라'],['프렌치 호른','합창 패드'],['팀파니','콘트라베이스']];
 else if(/뉴에이지|앰비언트|로파이|치유/.test(`${g} ${m}`))pools=[['그랜드 피아노','전자피아노','하프'],['전자 패드','합창 패드'],['첼로 섹션','비올라','바이올린 섹션'],['어쿠스틱 기타','플루트']];
 else if(/발라드|어쿠스틱|포크|컨트리/.test(g))pools=[['그랜드 피아노','피아노','어쿠스틱 기타'],['어쿠스틱 기타','전자피아노'],['베이스 기타','첼로 섹션'],['바이올린 섹션','전자 패드','플루트']];
 else if(/힙합|랩|트랩|R&B|소울|펑크/.test(g))pools=[['전자피아노','신시사이저'],['808 베이스','베이스 기타'],['드럼 세트'],['색소폰','전자 패드','일렉 기타']];
 else if(/트로트/.test(g))pools=[['전자피아노','피아노'],['베이스 기타'],['드럼 세트'],['트럼펫','색소폰','일렉 기타']];
 else pools=[['피아노','전자피아노','어쿠스틱 기타'],['일렉 기타','어쿠스틱 기타','신시사이저'],['베이스 기타','808 베이스'],['드럼 세트','전자 패드','바이올린 섹션']];
 const out=[];pools.forEach((pool,i)=>{const options=pool.filter(n=>!out.includes(n));if(options.length){const pickIndex=(storySeed(`${seed}|${i}|${salt}`)+salt+i)%options.length;out.push(options[pickIndex])}});
 if(p.meter==='6/8'&&out.includes('드럼 세트')&&!/록|댄스|EDM/.test(g)){out.splice(out.indexOf('드럼 세트'),1);const alt=stablePick(['첼로 섹션','전자 패드','하프','플루트'].filter(n=>!out.includes(n)),1,seed^0x55aa)[0];if(alt)out.push(alt)}
 return [...new Set(out)].slice(0,4);
}


function readLearningMemory(){try{const raw=JSON.parse(localStorage.getItem(LEARNING_MEMORY_KEY)||'null');if(raw&&Array.isArray(raw.items))return{version:1,items:raw.items.slice(-LEARNING_MAX_ITEMS)};return{version:1,items:[]}}catch(e){return{version:1,items:[]}}}
function writeLearningMemory(mem){try{const clean={version:1,updatedAt:new Date().toISOString(),items:(mem?.items||[]).slice(-LEARNING_MAX_ITEMS)};localStorage.setItem(LEARNING_MEMORY_KEY,JSON.stringify(clean));return true}catch(e){toast('학습 기억 저장 공간이 부족합니다. 백업 후 오래된 학습곡을 지워 주세요.');return false}}
function learningIsEnabled(){const el=$('#learningEnabled');if(el)return !!el.checked;try{return localStorage.getItem(LEARNING_ENABLED_KEY)!=='0'}catch(e){return true}}
function setLearningEnabled(v){try{localStorage.setItem(LEARNING_ENABLED_KEY,v?'1':'0')}catch(e){}renderLearningProfile()}
function learningSimilarity(item,p){let s=1;const g=String(p?.genre||''),ig=String(item.genre||'');if(g&&ig){if(g===ig)s+=5;else if((/발라드/.test(g)&&/발라드/.test(ig))||(/록/.test(g)&&/록/.test(ig))||(/댄스|EDM|하우스|테크노/.test(g)&&/댄스|EDM|하우스|테크노/.test(ig))||(/뉴에이지|앰비언트|로파이/.test(g)&&/뉴에이지|앰비언트|로파이|어쿠스틱/.test(ig)))s+=3}if(p?.meter&&item.meter===p.meter)s+=2;if(Number.isFinite(p?.bpm)&&Number.isFinite(item.bpm))s+=Math.max(0,2-Math.abs(p.bpm-item.bpm)/18);s+=Math.max(-.7,Math.min(.7,Number(item.rating||0)*.2));return Math.max(.2,s)}
function learningNeighbors(p,limit=12){if(!learningIsEnabled())return[];return readLearningMemory().items.map(x=>({x,w:learningSimilarity(x,p)})).sort((a,b)=>b.w-a.w).slice(0,limit)}
function learnedProfileFor(p){const rows=learningNeighbors(p,16);if(!rows.length)return null;let ws=0,bpm=0;const meters={},genres={},inst={},mix={transient:0,bassLikelihood:0,presenceLikelihood:0,sustainLikelihood:0};for(const {x,w} of rows){ws+=w;bpm+=(Number(x.bpm)||0)*w;if(x.meter)meters[x.meter]=(meters[x.meter]||0)+w;if(x.genre)genres[x.genre]=(genres[x.genre]||0)+w;for(const n of x.instruments||[])inst[n]=(inst[n]||0)+w;for(const k of Object.keys(mix))mix[k]+=(Number(x.mixHints?.[k])||0)*w}const top=o=>Object.entries(o).sort((a,b)=>b[1]-a[1]);return{count:rows.length,totalWeight:ws,bpm:ws?bpm/ws:null,meter:top(meters)[0]?.[0]||'',genre:top(genres)[0]?.[0]||'',instruments:top(inst).slice(0,8).map(([name,score])=>({name,score})),mixHints:Object.fromEntries(Object.entries(mix).map(([k,v])=>[k,ws?v/ws:0]))}}
function applyLearnedTasteToProfile(p){const lp=learnedProfileFor(p);if(!lp)return p;const out={...p,learningProfile:lp};if(Number.isFinite(lp.bpm)&&Math.abs(lp.bpm-out.bpm)<=32)out.bpm=Math.round(out.bpm*.72+lp.bpm*.28);const meterShare=lp.meter?learningNeighbors(p,16).filter(r=>r.x.meter===lp.meter).reduce((s,r)=>s+r.w,0)/Math.max(.001,lp.totalWeight):0;if(lp.meter&&meterShare>.58)out.meter=lp.meter;return out}
function learnedPreferredInstrumentNames(p,limit=5){const lp=learnedProfileFor(p);return(lp?.instruments||[]).slice(0,limit).map(x=>x.name)}
function reorderWithLearning(list,p){const pref=learnedPreferredInstrumentNames(p,8);if(!pref.length)return list;const rank=new Map(pref.map((n,i)=>[n,i]));return [...list].sort((a,b)=>(rank.has(a)?rank.get(a):-1)-(rank.has(b)?rank.get(b):-1)).reverse()}
function learningItemFromAnalysis(a,extra={}){if(!a)return null;return{id:extra.id||`${Date.now()}-${Math.random().toString(36).slice(2,8)}`,name:extra.name||a.fileName||'분석곡',learnedAt:new Date().toISOString(),source:extra.source||'current',rating:Number(extra.rating||0),duration:Number(a.duration||0),bpm:Number(a.bpm||0),meter:a.meter||'',key:a.key||'',genre:a.character?.genre||a.genre||'',mood:a.character?.mood||a.mood||'',instruments:[...(a.instruments||[])].slice(0,8),mixHints:{transient:Number(a.mixHints?.transient||0),bassLikelihood:Number(a.mixHints?.bassLikelihood||0),presenceLikelihood:Number(a.mixHints?.presenceLikelihood||0),sustainLikelihood:Number(a.mixHints?.sustainLikelihood||0)},confidence:{tempo:Number(a.tempoConfidence||0),meter:Number(a.meterConfidence||0),key:Number(a.keyConfidence||0),melody:Number(a.reliability||0),chord:Number(a.chordConfidence||0)},auto64Summary:a.auto64Mix?.summary||''}}
function addLearningItem(item,silent=false){if(!item)return false;const mem=readLearningMemory(),sig=`${item.name}|${Math.round(item.duration||0)}|${item.bpm}|${item.meter}|${item.key}`;const duplicate=mem.items.findIndex(x=>`${x.name}|${Math.round(x.duration||0)}|${x.bpm}|${x.meter}|${x.key}`===sig);if(duplicate>=0)mem.items.splice(duplicate,1);mem.items.push(item);const ok=writeLearningMemory(mem);renderLearningProfile();if(ok&&!silent)toast(`AI 학습 기억에 저장: ${item.name}`);return ok}
function removeLearningItem(id){const mem=readLearningMemory(),x=mem.items.find(x=>x.id===id);if(!x)return;mem.items=mem.items.filter(x=>x.id!==id);writeLearningMemory(mem);renderLearningProfile();toast('선택한 학습 기억을 삭제했습니다')}
function learningSummaryText(mem=readLearningMemory()){const items=mem.items;if(!items.length)return'아직 학습한 곡이 없습니다.';const avg=items.reduce((s,x)=>s+(Number(x.bpm)||0),0)/items.length,meters={},genres={},inst={};for(const x of items){if(x.meter)meters[x.meter]=(meters[x.meter]||0)+1;if(x.genre)genres[x.genre]=(genres[x.genre]||0)+1;for(const n of x.instruments||[])inst[n]=(inst[n]||0)+1}const top=o=>Object.entries(o).sort((a,b)=>b[1]-a[1])[0]?.[0]||'—',tops=Object.entries(inst).sort((a,b)=>b[1]-a[1]).slice(0,5).map(x=>x[0]).join(' · ')||'—';return`${items.length}곡 기억 · 평균 ${Math.round(avg)} BPM · 자주 나온 박자 ${top(meters)}\n자주 나온 장르 ${top(genres)} · 악기 성향 ${tops}\n${learningIsEnabled()?'✓ 다음 작곡·악기·믹싱 추천에 자동 반영 중':'학습 기억 반영 꺼짐'}`}
function renderLearningProfile(){const mem=readLearningMemory(),count=$('#learningCount'),profile=$('#learningProfile'),items=$('#learningItems'),enabled=$('#learningEnabled');if(enabled){let v=true;try{v=localStorage.getItem(LEARNING_ENABLED_KEY)!=='0'}catch(e){}enabled.checked=v}if(count)count.textContent=`${mem.items.length}곡 학습 기억`;if(profile){profile.textContent=learningSummaryText(mem);profile.classList.toggle('learning-profile-good',mem.items.length>=5)}if(items){const last=[...mem.items].reverse().slice(0,12);items.innerHTML=last.length?last.map(x=>`<div class="learning-item"><div><b>${esc(x.name||'학습곡')}</b><small>${x.bpm||'—'} BPM · ${esc(x.meter||'—')} · ${esc(x.key||'—')} · ${esc(x.genre||'장르 추정')}<br>${esc((x.instruments||[]).slice(0,4).join(' · ')||'악기 역할 추정')}</small></div><button class="danger" data-learning-delete="${esc(x.id)}">삭제</button></div>`).join(''):'<div class="learning-item"><div><b>아직 학습한 곡이 없습니다.</b><small>AI 학습곡 추가를 눌러 참고 음원을 넣어 주세요.</small></div></div>';$$('[data-learning-delete]').forEach(b=>b.onclick=()=>removeLearningItem(b.dataset.learningDelete))}}
async function analyzeLearningFile(file,index,total){const ac=new(window.AudioContext||window.webkitAudioContext)();try{const buffer=await ac.decodeAudioData(await file.arrayBuffer()),rate=8000,data=monoDownsample(buffer,rate),tempo=estimateTempoVerified(data,rate),meterInfo=estimateMeterVerified(tempo),keyInfo=estimateKeyVerified(data,rate),character=estimateAudioCharacter(data,tempo.bpm),mixHints=bandRoleHints(data,rate,tempo),instruments=audioInstrumentSuggestion({...character,bpm:tempo.bpm,meter:meterInfo.meter},mixHints),a={fileName:file.name,duration:buffer.duration,bpm:tempo.bpm,meter:meterInfo.meter,key:keyInfo.key,keyConfidence:keyInfo.confidence,tempoConfidence:tempo.confidence,meterConfidence:meterInfo.confidence,character,mixHints,instruments,reliability:0,chordConfidence:0};return learningItemFromAnalysis(a,{name:file.name,source:'learning-file'})}finally{try{await ac.close()}catch(e){}}}
